ALTER TABLE alert_rules ADD COLUMN managed INTEGER NOT NULL DEFAULT 0 CHECK(managed IN(0,1));
ALTER TABLE alert_rules ADD COLUMN retired_at TEXT;
ALTER TABLE alert_rules ADD COLUMN name TEXT NOT NULL DEFAULT 'Règle historique';
ALTER TABLE alert_rules ADD COLUMN escalation_days INTEGER NOT NULL DEFAULT 7 CHECK(escalation_days BETWEEN 1 AND 365);
ALTER TABLE alert_rules ADD COLUMN created_at TEXT;
CREATE UNIQUE INDEX alert_rules_current ON alert_rules(organisation_id,coalesce(building_id,''),deadline_kind) WHERE managed=1 AND retired_at IS NULL;
ALTER TABLE alerts ADD COLUMN managed INTEGER NOT NULL DEFAULT 0 CHECK(managed IN(0,1));
ALTER TABLE alerts ADD COLUMN severity INTEGER NOT NULL DEFAULT 2 CHECK(severity BETWEEN 1 AND 4);
ALTER TABLE alerts ADD COLUMN opened_at TEXT;
ALTER TABLE alerts ADD COLUMN resolution_kind TEXT;
CREATE TABLE alert_events(id TEXT PRIMARY KEY,alert_id TEXT NOT NULL REFERENCES alerts(id),actor_id TEXT REFERENCES users(id),created_at TEXT NOT NULL,kind TEXT NOT NULL,note TEXT NOT NULL) STRICT;
CREATE INDEX alert_events_order ON alert_events(alert_id,created_at,id);
CREATE TRIGGER alert_events_no_update BEFORE UPDATE ON alert_events BEGIN SELECT RAISE(ABORT,'Alert events are immutable'); END;
CREATE TRIGGER alert_events_no_delete BEFORE DELETE ON alert_events BEGIN SELECT RAISE(ABORT,'Alert events are immutable'); END;
CREATE TABLE manual_deadlines(deadline_id TEXT PRIMARY KEY REFERENCES deadlines(id),title TEXT NOT NULL,notes TEXT NOT NULL,restricted INTEGER NOT NULL DEFAULT 0 CHECK(restricted IN(0,1)),created_by TEXT NOT NULL REFERENCES users(id),created_at TEXT NOT NULL,previous_id TEXT REFERENCES manual_deadlines(deadline_id),completed_by TEXT REFERENCES users(id),completion_note TEXT) STRICT;
CREATE TABLE notification_attempts(id TEXT PRIMARY KEY,notification_id TEXT NOT NULL REFERENCES notifications(id),attempted_at TEXT NOT NULL,state TEXT NOT NULL CHECK(state IN('delivered','failed')),message TEXT NOT NULL) STRICT;
CREATE TRIGGER notification_attempts_no_update BEFORE UPDATE ON notification_attempts BEGIN SELECT RAISE(ABORT,'Notification attempts are immutable'); END;
CREATE TRIGGER notification_attempts_no_delete BEFORE DELETE ON notification_attempts BEGIN SELECT RAISE(ABORT,'Notification attempts are immutable'); END;
INSERT INTO permissions VALUES('alerts.manage'),('alerts.ack');
INSERT INTO role_permissions SELECT code,'alerts.manage' FROM roles WHERE code IN('exploitant','securite','technique');
INSERT INTO role_permissions SELECT code,'alerts.ack' FROM roles WHERE code IN('exploitant','securite','technique','agent');
CREATE INDEX alerts_active ON alerts(resolved_at,deadline_id);
CREATE INDEX notifications_due ON notifications(user_id,state,next_attempt_at);
